{
  "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
  "type": "AdaptiveCard",
  "version": "1.5",
  "body": [
    {
      "type": "TextBlock",
      "size": "Large",
      "weight": "Bolder",
      "id": "Title",
      "text": "@{triggerBody()?['text_2']} meeting initiated for project @{triggerBody()?['text_1']}",
      "horizontalAlignment": "Left",
      "isSubtle": false,
      "style": "heading"
    },
    {
      "type": "TextBlock",
      "text": "@{triggerBody()?['text_2']} meeting for project @{triggerBody()?['text_1']}, initiated by Project Manager/ Developer @{triggerBody()?['text_8']}, was approved by Portfolio Manager @{triggerBody()?['text_13']}.\n\nRequest Due Date: @{first(split(triggerBody()?['text_9'], ' '))}\n\nRequest comment: @{triggerBody()?['text_3']}\n",
      "wrap": true,
      "spacing": "Medium"
    },
    {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Project details:",
      "weight": "Bolder",
      "size": "Large",
      "horizontalAlignment": "Left",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Name",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Value",
              "weight": "Bolder",
              "style": "columnHeader"
            }
          ]
        }
      ]
    },
    @{triggerBody()?['text_15']},
    {
      "type": "Container",
      "items": [
        {
          "type": "TextBlock",
          "wrap": true,
          "height": "stretch"
        }
      ],
      "separator": true,
      "minHeight": "32px"
    },
    {
      "type": "TextBlock",
      "text": "Check List:",
      "weight": "Bolder",
      "size": "Large",
      "spacing": "Medium",
      "isSubtle": true
    },
    {
      "type": "ColumnSet",
      "spacing": "Small",
      "columns": [
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "State",
              "weight": "Bolder",
              "wrap": true
            }
          ]
        },
        {
          "type": "Column",
          "width": "stretch",
          "items": [
            {
              "type": "TextBlock",
              "text": "Description",
              "weight": "Bolder",
              "wrap": true
            }
          ]
        }

      ]
    },
    @{triggerBody()?['text_14']}
  ]
}

